package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.character.*;
import dev.tacticalcombat.uiapi.*;
import java.nio.file.*;
import java.util.*;
import org.lwjgl.glfw.GLFW;
import static dev.tacticalcombat.client.ui.ManagementState.*;
import static dev.tacticalcombat.uiapi.UiApiService.Operation.*;

/** Checkpoint B integration tests against real repositories and the existing authorization service. */
public final class CharacterSheetCheckpointTests {
    private static int count;
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);count++;}
    private static JsonObject ok(UiApiService api,CharacterRepository.Principal p,UiApiService.Operation op,JsonObject args){var r=api.handle(p,op,args);check(r.code().equals("OK"),op+": "+r.message());return r.data();}
    private static JsonObject item(String id,String name){return SheetSections.JSON.toJsonTree(new SheetSections.Item(id,"srd:weapon:LONGSWORD",name,1,false,"main_hand",List.of("VERSATILE"),"Legacy notes","minecraft:iron_sword")).getAsJsonObject();}
    private static final class AckScreen extends ManagementScreen {
        AckScreen(){super("Acknowledgement check",null);}
        @Override protected void refresh(){}
        @Override protected void request(UiApiService.Operation op,JsonObject args,java.util.function.Consumer<UiApiService.Reply> callback){callback.accept(new UiApiService.Reply("OK","",new JsonObject()));}
        boolean freshState(){return fresh;}
        void badRead(){read(LIBRARY_GET,new JsonObject(),data->{throw new IllegalArgumentException("Incomplete snapshot");});}
        void badSave(){fresh=true;mutate(LIBRARY_UPDATE,new JsonObject(),data->{throw new IllegalArgumentException("Incomplete acknowledgement");});}
    }
    public static void run()throws Exception {
        check(Arrays.stream(CreatorFlow.Step.values()).map(s->s.title).toList().equals(List.of("Identity","Class","Ability Points","Proficiencies","Equipment","Features","Spells","Character Details","Review & Finish")),"Nine creator destinations preserved");
        check(Arrays.stream(DashboardModel.Tab.values()).map(DashboardModel::title).toList().equals(List.of("Character Sheet","Skills & Saving Throws","Inventory & Equipment","Features","Spells","Character Background")),"Six dashboard destinations in required order");
        for(int[] size:List.of(new int[]{320,240},new int[]{480,270},new int[]{640,360},new int[]{960,540},new int[]{1280,720})){var frame=UiLayout.frame(size[0],size[1],980);var body=DashboardLayout.body(frame);var nav=DashboardLayout.navigation(frame);var manage=DashboardLayout.management(frame);check(body.fits(size[0],size[1])&&nav.fits(size[0],size[1])&&manage.fits(size[0],size[1]),"Dashboard regions fit logical size");check(!body.overlaps(nav)&&!body.overlaps(manage)&&!nav.overlaps(manage),"Management button is separate from destinations and sheet");for(var r:DashboardLayout.tabs(frame))check(!r.overlaps(manage),"Tab hitboxes cannot trigger Manage");var inventory=InventoryWorkspace.geometry(frame);for(var r:inventory)check(r.fits(size[0],size[1])&&r.y()+r.height()<=frame.y()+frame.height()-30,"Inventory summary and picker clear footer");check(!inventory[0].overlaps(inventory[1]),"Picker and item summary stay separate");var stats=CharacterSheetUi.columns(body.width(),4,6,45);for(var r:stats)check(r.x()>=0&&r.x()+r.width()<=body.width(),"Formatted stat cards fit sheet width");for(int i=0;i<stats.size();i++)for(int j=i+1;j<stats.size();j++)check(!stats.get(i).overlaps(stats.get(j)),"Formatted stat panels do not overlap");}
        var canvas=new CharacterCanvas(new UiLayout.Rect(0,0,240,180));var layout=IdentityLayout.layout(240,180,s->s.length()*6);var races=new ArrayList<String>();canvas.control("races",new IdentityRaceGrid(layout,"Human",races::add));var alignments=new ArrayList<String>();var current=new String[]{"True Neutral"};var dropdown=canvas.control("alignment",new AlignmentDropdown(5,40,120,()->current[0],v->{current[0]=v;alignments.add(v);},()->new UiLayout.Rect(0,0,240,180)));
        for(int i=0;i<4;i++){check(canvas.mouseClicked(10,44,0)&&dropdown.isOpen(),"Alignment can reopen repeatedly");check(canvas.mouseClicked(10,60,0)&&!dropdown.isOpen(),"Alignment option can be selected repeatedly");}
        check(alignments.size()==4&&races.isEmpty(),"Alignment selection never passes through to race");check(canvas.mouseClicked(10,44,0)&&canvas.mouseClicked(170,70,0)&&!dropdown.isOpen()&&races.isEmpty(),"Outside click dismisses popup without choosing underlying race");check(canvas.mouseClicked(10,44,0)&&canvas.dismissPopup()&&!dropdown.isOpen(),"Creator Escape path dismisses popup first");check(canvas.mouseClicked(10,44,0)&&canvas.mouseClicked(10,44,0)&&!dropdown.isOpen(),"Clicking alignment field toggles popup without choosing option");
        var ack=new AckScreen();try{ack.badRead();throw new AssertionError("Bad read accepted");}catch(IllegalArgumentException expected){count++;}check(!ack.freshState(),"Invalid read leaves controls untrusted until refresh");try{ack.badSave();throw new AssertionError("Bad save accepted");}catch(IllegalArgumentException expected){count++;}check(!ack.freshState(),"Invalid acknowledgement cannot re-enable edits or claim saved data");
        var definition=SheetSections.JSON.toJsonTree(new SheetSections.SpellDefinition("custom:light","Light",0,"Evocation","1 action","Touch","1 hour",true,false,true,"a firefly",false,false,"A target sheds light.","","Personal spell",true)).getAsJsonObject();var selection=SheetSections.JSON.toJsonTree(new SheetSections.SpellSelection("custom:light",true,true,false,"Personal spell","")).getAsJsonObject();var spell=SpellReference.entry(definition,selection);check(spell.id().equals("custom:light")&&spell.action().equals("1 action")&&spell.description().contains("Prepared")&&spell.detail().contains("no effect is applied"),"Spell inspection shows real metadata without a casting action");
        var dir=Files.createTempDirectory("sheet-b");var repo=new CharacterRepository(dir.resolve("campaigns.json"));var library=new LibraryRepository(dir.resolve("library.json"));var api=new UiApiService(repo,library,(op,a)->{throw new IllegalArgumentException("No world adapter");});var owner=new CharacterRepository.Principal(UUID.randomUUID(),true);var outsider=new CharacterRepository.Principal(UUID.randomUUID(),false);
        var draft=ok(api,owner,LIBRARY_CREATE,args("profile","srd_5_1","mode","GUIDED","sheet",dev.tacticalcombat.rules.srd.SrdAuthoring.template().toString()));String id=text(draft,"id");var source=new DashboardSource(true,id);var identity=SheetSections.read(draft.getAsJsonObject("sheet"),"identity");identity.addProperty("species","Elf — High Elf");identity.addProperty("characterClass","Fighter");identity.addProperty("background","Legacy Acolyte");identity.addProperty("age","120");identity.addProperty("height","Six feet");identity.addProperty("alignment","Neutral Good");identity.addProperty("biography","First paragraph\n\nSecond paragraph");draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"identity",identity));
        var prof=SheetSections.read(draft.getAsJsonObject("sheet"),"proficiencies");prof.getAsJsonArray("skills").add("Athletics");prof.getAsJsonArray("skills").add("athletics");prof.getAsJsonArray("saves").add("Strength");prof.getAsJsonArray("saves").add("str");prof=ProficiencyModel.normalized(prof);check(array(prof,"skills").size()==1&&array(prof,"saves").size()==1,"Case/ability aliases cannot create duplicate grants");prof=ProficiencyModel.toggle(prof,"expertise","Athletics");check(ProficiencyModel.contains(prof,"skills","Athletics")&&ProficiencyModel.contains(prof,"expertise","Athletics"),"Expertise includes one proficiency");var projected=draft.deepCopy();projected.add("sheet",SheetSections.update(projected.getAsJsonObject("sheet"),"proficiencies",prof));var athletics=ProficiencyModel.checks(projected,false).stream().filter(c->c.name().equals("Athletics")).findFirst().orElseThrow();check(athletics.proficiency()==4&&athletics.expertise(),"Expertise doubles the level-one bonus once, not twice");prof=ProficiencyModel.toggle(prof,"skills","Athletics");check(!ProficiencyModel.contains(prof,"skills","Athletics")&&!ProficiencyModel.contains(prof,"expertise","Athletics"),"Removing proficiency removes associated expertise");check(ProficiencyModel.checks(projected,false).size()==18&&ProficiencyModel.checks(projected,true).size()==6,"Skills and saves share one complete workspace");
        var inventory=SheetSections.read(draft.getAsJsonObject("sheet"),"inventory");var sword=item("custom:first","Longsword");inventory=InventoryModel.upsert(inventory,sword);for(int i=0;i<5;i++)inventory=InventoryModel.upsert(inventory,sword);check(array(inventory,"items").size()==1,"Stable add/edit retry is idempotent");inventory=InventoryModel.upsert(inventory,item("custom:second","Longsword"));var entries=InventoryModel.entries(inventory,InventoryModel.Category.ALL,"");check(entries.size()==2&&!entries.get(0).label().equals(entries.get(1).label()),"Identical names have distinct display identities");check(InventoryModel.entries(inventory,InventoryModel.Category.WEAPONS,"legacy").size()==2&&InventoryModel.entries(inventory,InventoryModel.Category.ARMOR,"").isEmpty(),"Category and description search preserve item identity");inventory=InventoryModel.quantity(inventory,"custom:first",4);inventory=InventoryModel.equipped(inventory,"custom:first");check(array(inventory,"items").size()==2&&InventoryModel.find(inventory,"custom:first").get("quantity").getAsInt()==5&&flag(InventoryModel.find(inventory,"custom:first"),"equipped"),"Quantity/equipped state changes intended item without adding duplicates");check(InventoryModel.find(inventory,"custom:second").get("quantity").getAsInt()==1,"Other identical record stays untouched");var beforeCombat=draft.getAsJsonObject("sheet").getAsJsonObject("collections").get("srd_combat").deepCopy();draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",inventory));check(beforeCombat.equals(draft.getAsJsonObject("sheet").getAsJsonObject("collections").get("srd_combat")),"Equipment bookkeeping cannot change combat inputs");
        long stale=revision(draft);var cached=draft.deepCopy();draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",InventoryModel.quantity(inventory,"custom:second",1)));check(api.handle(owner,LIBRARY_UPDATE,args("character",id,"revision",stale,"section","inventory","data",inventory)).code().equals("CONFLICT"),"Stale inventory save rejected");for(int i=0;i<4;i++){var reopened=ok(api,owner,LIBRARY_GET,source.readArgs());check(array(SheetSections.read(reopened.getAsJsonObject("sheet"),"inventory"),"items").size()==2,"Refresh/reopen does not add items");}check(api.handle(outsider,LIBRARY_UPDATE,source.sectionArgs(draft,"inventory",inventory)).code().equals("FORBIDDEN"),"Unauthorized inventory mutation rejected");try{SnapshotReplies.checked(source,args("id",id,"revision",1));throw new AssertionError("Partial snapshot published");}catch(IllegalArgumentException expected){count++;}check(array(SheetSections.read(cached.getAsJsonObject("sheet"),"inventory"),"items").size()==2,"Malformed replies cannot mutate cached records");
        var story=SheetSections.read(draft.getAsJsonObject("sheet"),"identity");story.addProperty("biography","A revised story\nwith retained paragraphs");draft=ok(api,owner,LIBRARY_UPDATE,source.sectionArgs(draft,"identity",story));var actual=SheetSections.read(draft.getAsJsonObject("sheet"),"identity");for(String key:List.of("species","background","age","height","alignment"))check(text(actual,key).equals(text(identity,key)),"Narrative saves preserve basic Identity: "+key);
        draft=ok(api,owner,LIBRARY_FINALIZE,args("character",id,"revision",revision(draft)));var campaign=ok(api,owner,CAMPAIGN_CREATE,args("name","Sheet B"));var copy=ok(api,owner,LIBRARY_SUBMIT,args("character",id,"revision",revision(draft),"campaign",text(campaign,"id"),"submission",UUID.randomUUID()));var campaignSource=new DashboardSource(false,text(copy,"id"));SnapshotReplies.checked(campaignSource,copy);var copyInventory=SheetSections.read(copy.getAsJsonObject("sheet"),"inventory");copy=ok(api,owner,CHARACTER_EDIT,campaignSource.sectionArgs(copy,"inventory",InventoryModel.quantity(copyInventory,"custom:first",1)));check(InventoryModel.find(SheetSections.read(ok(api,owner,LIBRARY_GET,source.readArgs()).getAsJsonObject("sheet"),"inventory"),"custom:first").get("quantity").getAsInt()==5,"Campaign inventory is independent from library source");copy=ok(api,owner,CHARACTER_APPROVE,args("character",campaignSource.character(),"revision",revision(copy)));repo.bind(owner,UUID.fromString(campaignSource.character()),revision(copy),owner.id(),owner.id());copy=ok(api,owner,CHARACTER_GET,campaignSource.readArgs());check(!DashboardModel.editable(copy,false,owner.id().toString(),false),"Bound inventory UI is read-only");check(!api.handle(owner,CHARACTER_EDIT,campaignSource.sectionArgs(copy,"inventory",InventoryModel.equipped(copyInventory,"custom:first"))).code().equals("OK"),"Server also rejects bound inventory edits");
        var restarted=new LibraryRepository(dir.resolve("library.json")).get(owner,UUID.fromString(id));var restartedSheet=JsonParser.parseString(restarted.sheet()).getAsJsonObject();check(array(SheetSections.read(restartedSheet,"inventory"),"items").size()==2&&text(SheetSections.read(restartedSheet,"identity"),"background").equals("Legacy Acolyte"),"Inventory and legacy fields survive repository restart");
        System.out.println("Character sheet checkpoint B checks passed: "+count);
    }
}
